'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var floor = require( '@stdlib/math/base/special/floor' );
var pow = require( '@stdlib/math/base/special/pow' );


// MAIN //

/**
* Returns the Kronecker product `S^{⊗L} ⊗ J`, where `S` is a `2×2` matrix and `J` is a `j×j` matrix of ones, as a dense row-major matrix.
*
* ## Notes
*
* -   The returned matrix has order `n = 2^L·j`. Element `(r,c)` equals the product over `l = 0, 1, ..., L-1` of `S[b_l(R),b_l(C)]`, where `R = floor(r/j)`, `C = floor(c/j)`, and `b_l(x)` denotes bit `l` of `x`.
* -   For `S = [[-1,-1],[1,1]]` and `T = [[1,-1],[-1,1]]`, `S*T = 0`, and, thus, `(S^{⊗L} ⊗ J)*(T^{⊗L} ⊗ J) = (S*T)^{⊗L} ⊗ J^2 = 0`, while the operand sums and products formed by the Strassen–Winograd recursion attain their worst-case growth (operand sums `S2 = 3A'` and `T2 = 3B'` at every level, such that leaf products reach `K·4.5^L·max|a|·max|b|`).
*
* @private
* @param {Collection} S - `2×2` matrix stored in row-major order (i.e., `[ s11, s12, s21, s22 ]`)
* @param {NonNegativeInteger} L - number of Kronecker factors
* @param {PositiveInteger} j - order of the matrix of ones
* @returns {Float64Array} matrix of order `2^L·j` stored in row-major order
*/
function kroneckerSign( S, L, j ) {
	var out;
	var bit;
	var br;
	var bc;
	var n;
	var v;
	var r;
	var c;
	var l;

	n = pow( 2, L ) * j;
	out = new Float64Array( n*n );
	for ( r = 0; r < n; r++ ) {
		for ( c = 0; c < n; c++ ) {
			v = 1.0;
			bit = 1;
			for ( l = 0; l < L; l++ ) {
				br = floor( floor( r/j ) / bit ) % 2;
				bc = floor( floor( c/j ) / bit ) % 2;
				v *= S[ ( 2*br )+bc ];
				bit *= 2;
			}
			out[ ( r*n )+c ] = v;
		}
	}
	return out;
}


// EXPORTS //

module.exports = kroneckerSign;
